actions.script:
const L = (text) => ec.l10n.localize(text)
newCode = ec.web.sessionAttributes.remove('newEdgePairingCode') || null
newCodeExpire = ec.web.sessionAttributes.remove('newEdgePairingExpire') || ''
linkKey = {linkFingerprint}
clientList = []
cursorList = []
nodeOptions = []
clientsError = ''
if (!isEdge) return
// a probe (Practices-App-Dev §4): a failure is shown on the page rather than failing it
let out = {}
let queueOut = {}
ec.message.pushErrors()
try {
    out = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeClients').call() || {}
    if (!ec.message.hasError()) queueOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#QueueStatus').call() || {}
    if (ec.message.hasError()) clientsError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (clientsError) return
// each node's queue: the items waiting for it (all kinds) and the failed ones, and the oldest waiting
const queues = {}
for (const kind of Array.from(queueOut.kindList || [])) {
    if (kind.directionEnumId !== 'EqdToLocal') continue
    const queue = queues[kind.pairedNodeId] ||
        (queues[kind.pairedNodeId] = {pending: 0, failed: 0, oldest: null})
    queue.pending += Number(kind.pending || 0)
    queue.failed += Number(kind.failed || 0)
    if (kind.oldestAgeSeconds != null) queue.oldest = Math.max(queue.oldest ?? 0, Number(kind.oldestAgeSeconds))
}
const age = (seconds) => seconds == null ? '' : seconds < 120 ? seconds + ' s' : seconds < 7200
    ? Math.round(seconds / 60) + ' min' : Math.round(seconds / 3600) + ' h'
cursorList = Array.from(queueOut.cursorList || []).map((cursor) => ({
    nodeId: cursor.pairedNodeId, setName: cursor.setName,
    epochText: cursor.epoch ? String(cursor.epoch).slice(0, 8) : '', seqText: String(cursor.sequenceNum ?? 0),
    valuesText: String(cursor.values ?? 0),
    appliedText: cursor.appliedDate ? ec.l10n.format(cursor.appliedDate, '') : '',
    snapshotText: cursor.snapshotDate ? ec.l10n.format(cursor.snapshotDate, '') : L('Not yet')}))
clientList = Array.from(out.clientList || []).map((client) => {
    const revoked = client.statusId === 'EdgeClientRevoked'
    const [stateLabel, stateColor] = revoked ? [L('Revoked'), 'negative']
        : client.linked && client.down ? [L('Linked'), 'positive']
        : client.linked ? [L('Connecting'), 'info'] : [L('Offline'), 'grey']
    const queue = queues[client.pairedNodeId]
    let queueText = L('Empty')
    if (queue) {
        queueText = queue.pending + ' ' + L('waiting')
        if (queue.oldest != null) queueText += ' (' + L('oldest') + ' ' + age(queue.oldest) + ')'
        if (queue.failed) queueText += ', ' + queue.failed + ' ' + L('failed')
    }
    return {pairedNodeId: client.pairedNodeId, stateLabel, stateColor, revoked, linked: !!client.linked && !!client.down,
        generationText: client.generation ? String(client.generation) : '',
        lastConnectText: client.lastConnectDate ? ec.l10n.format(client.lastConnectDate, '') : L('Never'),
        remoteAddress: client.remoteAddress || '',
        versionText: (client.binaryVersion || '') + (client.linkVersion ? ' · ' + L('link') + ' ' + client.linkVersion : ''),
        keyShort: client.keyFingerprint ? String(client.keyFingerprint).slice(0, 16) + '…' : '',
        queueText,
        capText: client.queueMaxMegabytes ? client.queueMaxMegabytes + ' MB' : L('The conf\'s')}
})
nodeOptions = clientList.filter((client) => !client.revoked).map((client) => ({nodeId: client.pairedNodeId}))
